import { BaseHandler } from "../../response/base.js";
import { validateDevFilePath } from "./path-validator.js";
import { bundleDevFile } from "./esbuild-bundler.js";
import { HTTP_INTERNAL_SERVER_ERROR, HTTP_NOT_FOUND, PRIORITY_MEDIUM_DEV_FILES, } from "../../../../utils/constants/index.js";
import { isExtendedFSAdapter } from "../../../../platform/adapters/fs/wrapper.js";
import { createHandlerDependencyPinningSource } from "../../utils/dependency-pinning-source.js";
import { readSnapshotQuery, resolveSnapshotForRequest, snapshotConflictResponse, snapshotStoreFailureResponse, } from "../../utils/dependency-snapshot-protocol.js";
import { createLocalControlAccessDeniedResponse, isTrustedLocalControlRequest, } from "../../../../security/http/local-control-request.js";
export class DevFileHandler extends BaseHandler {
    bundleFile;
    constructor(bundleFile = bundleDevFile) {
        super();
        this.bundleFile = bundleFile;
    }
    metadata = {
        name: "DevFileHandler",
        priority: PRIORITY_MEDIUM_DEV_FILES,
        patterns: [{ pattern: "/_veryfront/fs/", prefix: true, method: "GET" }],
        // Strictly local-only: exposes project source tree (VULN-SRV-1 / VULN-SRV-2).
        // Preview mode (even host-derived) must not unlock this surface.
        enabled: (ctx) => !!ctx.isLocalProject,
    };
    async handle(req, ctx) {
        const { pathname } = new URL(req.url);
        if (!ctx.isLocalProject)
            return this.continue();
        if (req.method !== "GET" || !pathname.startsWith("/_veryfront/fs/")) {
            return this.continue();
        }
        if (!isTrustedLocalControlRequest(req)) {
            return this.respond(createLocalControlAccessDeniedResponse(req, "Development file request rejected"));
        }
        const fsAdapter = ctx.adapter.fs;
        const isExtended = isExtendedFSAdapter(fsAdapter);
        if (isExtended && fsAdapter.isContextualMode()) {
            try {
                if (ctx.proxyToken)
                    fsAdapter.setRequestToken(ctx.proxyToken);
                fsAdapter.setRequestBranch(ctx.parsedDomain?.branch ?? null);
                fsAdapter.setProductionMode(false, ctx.releaseId);
            }
            catch (_) {
                /* expected: some fs adapter operations may not be supported */
            }
        }
        return await this.handleWithContext(req, pathname, ctx);
    }
    async handleWithContext(req, pathname, ctx) {
        const encoded = pathname.slice("/_veryfront/fs/".length).replace(/\.js$/, "");
        const validation = await validateDevFilePath(encoded, ctx);
        if (validation.kind === "rejected") {
            this.logDebug("dev fs validation failed", { message: validation.message }, ctx);
            return this.respond(this.createErrorModule(validation.message, HTTP_NOT_FOUND));
        }
        const absPath = validation.path;
        try {
            const requestUrl = new URL(req.url);
            const dependencyPinningSource = createHandlerDependencyPinningSource(ctx);
            const resolution = await resolveSnapshotForRequest(dependencyPinningSource, readSnapshotQuery(requestUrl));
            if (resolution.kind === "conflict") {
                return this.respond(snapshotConflictResponse(this.createResponseBuilder(ctx), req, ctx.securityConfig));
            }
            const dependencySnapshot = resolution.snapshot;
            const code = await this.bundleFile(absPath, ctx, dependencySnapshot, dependencyPinningSource, requestUrl.origin);
            const response = this.createResponseBuilder(ctx)
                .withCORS(req, ctx.securityConfig?.cors)
                .withSecurity(ctx.securityConfig ?? undefined, req)
                .withCache("no-cache")
                .javascript(code);
            return this.respond(response);
        }
        catch (error) {
            const storageFailure = snapshotStoreFailureResponse(error, this.createResponseBuilder(ctx), req, ctx.securityConfig);
            if (storageFailure)
                return this.respond(storageFailure);
            const reason = this.getErrorMessage(error);
            this.logDebug("dev fs request failed", { path: absPath, reason }, ctx);
            return this.respond(this.createErrorModule(`Build error: ${reason}`, HTTP_INTERNAL_SERVER_ERROR));
        }
    }
    createErrorModule(message, status) {
        return new Response(`export default null; // ${message}`, {
            status,
            headers: {
                "cache-control": "no-store",
                "content-type": "application/javascript",
            },
        });
    }
}
